INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-14', 'es', 'Ajustes más ordenados', 'Juego en línea ahora es la primera opción de Ajustes y Rutas pasa a Sistema. Nueva opción Interfaz > Ocultar botones para ver la lista de juegos sin los botones de abajo.'),
 ('2026-11-14', 'en', 'Tidier settings', 'Online play is now the first option in Settings and Paths moves into System. New option Interface > Hide buttons to see the game list without the buttons at the bottom.'),
 ('2026-11-14', 'pt', 'Ajustes mais organizados', 'Jogo online agora é a primeira opção dos Ajustes e Caminhos passa para Sistema. Nova opção Interface > Ocultar botões para ver a lista de jogos sem os botões de baixo.'),
 ('2026-11-14', 'fr', 'Réglages mieux rangés', 'Le jeu en ligne est maintenant la première option des Réglages et Chemins passe dans Système. Nouvelle option Interface > Masquer les boutons pour voir la liste des jeux sans les boutons du bas.'),
 ('2026-11-14', 'it', 'Impostazioni più ordinate', 'Il gioco online ora è la prima opzione delle Impostazioni e Percorsi passa in Sistema. Nuova opzione Interfaccia > Nascondi pulsanti per vedere la lista dei giochi senza i pulsanti in basso.'),
 ('2026-11-14', 'de', 'Aufgeräumte Einstellungen', 'Online-Spiel ist jetzt die erste Option der Einstellungen und Pfade wandert zu System. Neue Option Oberfläche > Tasten ausblenden für die Spieleliste ohne die Tasten unten.'),
 ('2026-11-14', 'ru', 'Настройки стали удобнее', 'Сетевая игра теперь первый пункт настроек, а Пути перенесены в Систему. Новый пункт Интерфейс > Скрыть кнопки, чтобы видеть список игр без кнопок внизу.');
